(()=>{
const base='assets/manter-no-alto/',colors=['vermelho','laranja','amarelo','verde','azul','roxo','rosa','turquesa'];
let level='easy',who='bluey',state=null,raf=0,last=0,acc=0,epoch=0,owned=false,assets=null,loading=null,stage=null,context=null;
let multiplayer=false,netToken=null,netTimer=0,netEpoch=0,netSequence=0,netCharacters=null,netSeat=0,netPhase='',netMisses=0,netReason='',visualPositions=new Map();
let music=null,musicEnabled=true,musicActive=false;
function musicSync(){if(!musicActive||!musicEnabled||document.hidden){music?.pause();return;}if(!music){music=new Audio('assets/audio/keepup-dance-mode-loop.mp3');music.loop=true;music.volume=.25;}music.play().catch(()=>{});}
function musicButton(){const button=document.createElement('button');button.className='ku-music';button.textContent=musicEnabled?'♫ Música ligada':'♪ Música desligada';button.setAttribute('aria-pressed',String(musicEnabled));button.onclick=()=>{musicEnabled=!musicEnabled;button.textContent=musicEnabled?'♫ Música ligada':'♪ Música desligada';button.setAttribute('aria-pressed',String(musicEnabled));musicSync();};(stage?.querySelector('.ku-hud')||app.querySelector('.ku-setup')).append(button);musicActive=true;musicSync();}
// A short synthesized latex pop; independent of the music toggle.
let popAudio=null,popBuffer=null;
const popSources=new Set();
function popReady(){try{if(!popAudio){popAudio=new (window.AudioContext||window.webkitAudioContext)();popBuffer=popAudio.createBuffer(1,Math.ceil(popAudio.sampleRate*.16),popAudio.sampleRate);const data=popBuffer.getChannelData(0);for(let i=0;i<data.length;i++){const t=i/popAudio.sampleRate,envelope=Math.min(1,t/.001)*Math.exp(-t*48);data[i]=((Math.random()*2-1)*.38+Math.sin(2*Math.PI*(190*t-350*t*t))*.25)*envelope;}}if(popAudio.state==='suspended')popAudio.resume().catch(()=>{});}catch{}}
function popSound(){if(!popAudio||popAudio.state!=='running'||document.hidden)return;try{const source=popAudio.createBufferSource();source.buffer=popBuffer;source.connect(popAudio.destination);popSources.add(source);source.onended=()=>{popSources.delete(source);source.disconnect();};source.start();}catch{}}
function stopPops(){for(const source of popSources){try{source.stop();}catch{}source.disconnect();}popSources.clear();}
function stepWithSound(dt,direction){const before=state.misses;KeepUpCore.step(state,dt,direction);for(let n=before;n<state.misses;n++)popSound();}
const keys=new Set(),pointers=new Map();
const files=['sala-bluey-v1.webp','bandit-deitado-v1.webp','chilli-cafe-v2.webp','bluey-sentada-v2.webp','bingo-sentada-v2.webp',...colors.map(c=>'balao-'+c+'-v1.webp'),...['bluey','bingo'].flatMap(c=>['01','02'].map(f=>c+'-perseguindo-direita-frame-'+f+'.webp'))];
function preload(){if(!loading)loading=Promise.all(files.map(f=>new Promise((resolve,reject)=>{const im=new Image(),timer=setTimeout(()=>reject(Error(f)),20000);im.onload=()=>{clearTimeout(timer);im.decode().then(()=>resolve([f,im]),reject)};im.onerror=()=>{clearTimeout(timer);reject(Error(f))};im.src=base+f}))).then(entries=>assets=Object.fromEntries(entries)).catch(e=>{loading=null;throw e});return loading;}
function release(){keys.clear();pointers.clear();}
function stop(keepFull=false){netStop();stopPops();musicActive=false;musicSync();epoch++;cancelAnimationFrame(raf);state=null;release();stage=null;if(owned&&!keepFull){owned=false;try{screen.orientation?.unlock()}catch{}if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});}}
function difficulties(){stop();memoryStop();stopSearchTimer();leaveSearchFullscreen();document.body.dataset.section='keepup';app.innerHTML='<section class="ku-setup"><button class="ku-back">← Jogos</button><p>BLUEY E BINGO · UMA BRINCADEIRA EM FAMÍLIA</p><h1>Manter no Alto <span>🎈</span></h1><h2>Escolha o desafio</h2><div class="ku-options">'+[['easy','Fácil',10],['medium','Médio',8],['hard','Difícil',6]].map(([id,name,seconds])=>'<button data-ku-level="'+id+'"><b>'+name+'</b><small>Um novo balão a cada '+seconds+' segundos</small></button>').join('')+'</div><p>Mantenha os balões no alto! A rodada termina após 3 estouros.</p></section>';app.querySelector('.ku-back').onclick=home;app.querySelectorAll('[data-ku-level]').forEach(b=>b.onclick=()=>{level=b.dataset.kuLevel;if(multiplayer)joinOnline();else characters()});musicButton();preload().catch(()=>{});}
function characters(){app.innerHTML='<section class="ku-setup"><button class="ku-back">← Dificuldade</button><p>MANTER NO ALTO</p><h1>Quem vai brincar?</h1><div class="ku-options ku-characters">'+['bluey','bingo'].map(c=>'<button data-ku-who="'+c+'"><img src="'+base+c+'-oficial.webp" alt="'+c+'"><b>'+c[0].toUpperCase()+c.slice(1)+'</b></button>').join('')+'</div><p>Use ← → no teclado ou segure as setas na tela.</p><small>Retratos: <a href="https://www.bluey.tv/characters/" target="_blank" rel="noopener">Bluey · site oficial</a></small></section>';app.querySelector('.ku-back').onclick=setup;app.querySelectorAll('[data-ku-who]').forEach(b=>b.onclick=()=>{who=b.dataset.kuWho;start()});musicButton();}
function resize(){if(!stage)return;const w=visualViewport?.width||innerWidth,h=visualViewport?.height||innerHeight,rotated=w<h;stage.classList.toggle('ku-rotated',rotated);stage.style.width=(rotated?h:w)+'px';stage.style.height=(rotated?w:h)+'px';const scale=Math.min((rotated?h:w)/1600,(rotated?w:h)/900);stage.querySelector('.ku-world').style.transform='translate(-50%,-50%) scale('+scale+')';}
function fullscreen(){if(!matchMedia('(pointer:coarse)').matches||document.fullscreenElement)return;try{const id=epoch;Promise.resolve(document.documentElement.requestFullscreen?.()).then(()=>{if(id!==epoch){if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});return}owned=!!document.fullscreenElement;if(owned)try{Promise.resolve(screen.orientation?.lock?.('landscape')).catch(()=>{})}catch{}resize()}).catch(()=>{});}catch{}}
async function start(online=false){online=online===true;if(!online)stop(true);popReady();const id=epoch;document.body.dataset.section='keepup';app.innerHTML='<section class="ku-stage"><div class="ku-world"><canvas width="1600" height="900" aria-label="Mantenha os balões no alto"></canvas><div class="ku-hud"><button id="ku-exit">← Voltar</button><span id="ku-score">Preparando a sala…</span></div><button class="ku-arrow ku-left" data-dir="-1" aria-label="Correr para a esquerda">❮</button><button class="ku-arrow ku-right" data-dir="1" aria-label="Correr para a direita">❯</button><div class="ku-overlay" role="status">Preparando a sala…</div></div></section>';stage=app.querySelector('.ku-stage');context=stage.querySelector('canvas').getContext('2d');stage.querySelector('#ku-exit').onclick=setup;stage.querySelectorAll('[data-dir]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();popReady();b.setPointerCapture(e.pointerId);pointers.set(e.pointerId,+b.dataset.dir)};for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,e=>pointers.delete(e.pointerId));});musicButton();resize();fullscreen();try{await preload();if(id!==epoch)return;stage.querySelector('.ku-overlay').remove();if(!online)state=KeepUpCore.create(level);last=0;acc=0;raf=requestAnimationFrame(tick);}catch{if(id!==epoch)return;const overlay=stage.querySelector('.ku-overlay');overlay.innerHTML='<p>Uma imagem não carregou.</p><button>Tentar novamente</button>';overlay.querySelector('button').onclick=()=>start(online);}}
function sprite(file,x,y,w,h,flip=false){const im=assets[file];context.save();if(flip){context.translate(x+w,y);context.scale(-1,1);context.drawImage(im,0,0,w,h)}else context.drawImage(im,x,y,w,h);context.restore();}
function smoothPosition(key,p){if(!netToken)return p;const old=visualPositions.get(key)||{x:p.x,y:p.y};old.x+=(p.x-old.x)*.35;old.y+=(p.y-old.y)*.35;visualPositions.set(key,old);return {...p,x:old.x,y:old.y};}
function draw(){context.clearRect(0,0,1600,900);sprite('sala-bluey-v1.webp',0,0,1600,900);sprite('bandit-deitado-v1.webp',335,380,320,160);sprite('chilli-cafe-v2.webp',28,300,187,280);
 // The unselected sister watches from the left side of the doorway.
 if(!netToken)sprite((who==='bluey'?'bingo':'bluey')+'-sentada-v2.webp',900,405,210,210);
 for(const raw of state.balloons){const b=smoothPosition('b'+raw.id,raw);sprite('balao-'+colors[b.color]+'-v1.webp',b.x-67,b.y-80,134,160);}
 for(const [index,raw] of (state.players||[state.player]).entries()){const p=smoothPosition('p'+index,raw),frame=Math.abs(p.vx)>15&&Math.floor(p.stride/65)%2?'02':'01';sprite((netToken?netCharacters[index]:who)+'-perseguindo-direita-frame-'+frame+'.webp',p.x-130,620,260,260,p.face<0);}
 for(const b of state.bursts){const t=b.age/.55;context.save();context.globalAlpha=1-t;context.strokeStyle=['#ef4444','#fb923c','#facc15','#4ade80','#38bdf8','#a855f7','#f472b6','#2dd4bf'][b.color]||'#fff';context.lineWidth=7*(1-t)+1;context.beginPath();context.arc(b.x,b.y,43+45*t,0,Math.PI*2);context.stroke();for(let i=0;i<10;i++){const a=i*Math.PI/5,r=40+100*t;context.beginPath();context.moveTo(b.x+Math.cos(a)*r,b.y+Math.sin(a)*r);context.lineTo(b.x+Math.cos(a)*(r+18),b.y+Math.sin(a)*(r+18));context.stroke();}context.restore();}
 stage.querySelector('#ku-score').textContent=Math.floor(state.elapsed)+' s · '+state.hits+' toques · '+state.balloons.length+' balões · '+state.misses+'/3 estourados';}
function tick(now){if(!state)return;if(!document.hidden){const dt=last?Math.min((now-last)/1000,.05):0;KeepUpCore.animate(state,dt);if(!state.over)acc+=dt;const left=keys.has('ArrowLeft')||keys.has('a')||[...pointers.values()].includes(-1),right=keys.has('ArrowRight')||keys.has('d')||[...pointers.values()].includes(1);while(!netToken&&acc>=1/120&&!state.over){stepWithSound(1/120,Number(right)-Number(left));acc-=1/120;}draw();for(const key of visualPositions.keys())if(key.startsWith('b')&&!state.balloons.some(b=>'b'+b.id===key))visualPositions.delete(key);if(state.over)release();if(state.over&&(!state.bursts.length||netToken)){const overlay=document.createElement('div');overlay.className='ku-overlay';overlay.innerHTML='<div><h2>Fim de jogo!</h2><p>'+netReason+'</p><p>Você manteve os balões no alto por '+Math.floor(state.elapsed)+' segundos!</p><button id="ku-again">Brincar de novo</button><button id="ku-choose">Trocar personagem</button></div>';stage.querySelector('.ku-world').append(overlay);overlay.querySelector('#ku-again').onclick=()=>netToken?joinOnline():start();overlay.querySelector('#ku-choose').onclick=setup;return;}}last=now;raf=requestAnimationFrame(tick);}
window.addEventListener('keydown',e=>{if(!state||!['ArrowLeft','ArrowRight','a','d'].includes(e.key))return;e.preventDefault();popReady();keys.add(e.key)});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',release);document.addEventListener('visibilitychange',()=>{release();last=0;acc=0;if(document.hidden)stopPops();musicSync()});window.addEventListener('resize',resize);window.visualViewport?.addEventListener('resize',resize);document.addEventListener('fullscreenchange',resize);

function setup(){stop();document.body.dataset.section='keepup';app.innerHTML='<section class="ku-setup"><button class="ku-back">← Jogos</button><h1>Manter no Alto 🎈</h1><h2>Quantas pessoas vão brincar?</h2><div class="ku-options"><button id="ku-one"><b>1 pessoa</b><small>Brinque com Bluey ou Bingo</small></button><button id="ku-two"><b>2 pessoas · online</b><small>Juntas na mesma sala, cada uma no seu aparelho</small></button></div></section>';app.querySelector('.ku-back').onclick=home;app.querySelector('#ku-one').onclick=()=>{multiplayer=false;difficulties()};app.querySelector('#ku-two').onclick=()=>{multiplayer=true;difficulties()};musicButton();}
function netStop(){netEpoch++;clearTimeout(netTimer);if(netToken)fetch('/api/keepup/leave',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+netToken},body:'{}',keepalive:true}).catch(()=>{});netToken=null;netPhase='';netCharacters=null;netReason='';visualPositions.clear();}
async function netAPI(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),5000);try{const response=await fetch('/api/keepup/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',...(netToken?{Authorization:'Bearer '+netToken}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:controller.signal});const data=await response.json();if(!response.ok)throw Object.assign(Error(data.error),{status:response.status});return data;}finally{clearTimeout(timer);}}
function netScreen(title,hint){app.innerHTML='<section class="ku-setup"><button class="ku-back">← Voltar</button><h1>'+title+'</h1><p role="status">'+hint+'</p><div class="ku-options ku-characters"></div></section>';app.querySelector('.ku-back').onclick=setup;musicButton();}
async function joinOnline(){stop(true);const run=netEpoch;netSequence=0;netMisses=0;netScreen('Aguardando outra pessoa…','Procurando alguém na mesma dificuldade.');try{const data=await netAPI('join',{level});if(run!==netEpoch){fetch('/api/keepup/leave',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+data.token},body:'{}',keepalive:true}).catch(()=>{});return;}netToken=data.token;await netAccept(data);netPoll(run);}catch{if(run===netEpoch)netScreen('Não foi possível conectar','Confira a conexão e se o servidor foi atualizado.');}}
async function netAccept(data){netReason=data.reason||'';netSeat=data.you??0;netCharacters=data.characters||netCharacters;if(data.phase==='characters'){const signature='characters:'+data.characters.join(',');if(netPhase!==signature){netPhase=signature;netScreen('Quem vai brincar?',data.characters[netSeat]?'Você escolheu '+data.characters[netSeat]+'. Aguardando a outra pessoa.':'Escolha Bluey ou Bingo. Cada pessoa terá uma personagem.');app.querySelector('.ku-options').innerHTML=['bluey','bingo'].map(c=>'<button data-net-char="'+c+'" '+(data.characters[1-netSeat]===c?'disabled':'')+'><img src="'+base+c+'-oficial.webp" alt="'+c+'"><b>'+c+'</b></button>').join('');app.querySelectorAll('[data-net-char]').forEach(b=>b.onclick=async()=>{popReady();fullscreen();const run=netEpoch;try{await netAPI('action',{kind:'character',character:b.dataset.netChar});}catch{}});}}
 if(data.state){for(let n=netMisses;n<data.state.misses;n++)popSound();netMisses=data.state.misses;state=data.state;if(netPhase!=='playing'){netPhase='playing';who=data.characters[netSeat];await start(true);}}
 if(data.phase==='over'&&!data.state){netScreen('A brincadeira terminou',data.reason||'Entre novamente para brincar.');}
}
async function netPoll(run){if(run!==netEpoch||!netToken)return;try{const direction=Number(keys.has('ArrowRight')||keys.has('d')||[...pointers.values()].includes(1))-Number(keys.has('ArrowLeft')||keys.has('a')||[...pointers.values()].includes(-1));const data=state&&!state.over?await netAPI('action',{kind:'input',direction,sequence:netSequence++}):await netAPI('state');if(run!==netEpoch)return;await netAccept(data);if(data.phase==='over')return;}catch(e){if(run!==netEpoch)return;if(e.status===401){stop();netScreen('Conexão encerrada','Volte e entre novamente para brincar.');return;}}if(run===netEpoch)netTimer=setTimeout(()=>netPoll(run),80);}
window.addEventListener('pagehide',netStop);

const oldHome=home;home=function(){stop();oldHome();const cards=app.querySelector('.game-cards');if(cards){cards.insertAdjacentHTML('beforeend','<button class="game-card ku-portal" id="ku-open"><div class="game-cover ku-cover"><img src="'+base+'sala-bluey-v1.webp" alt="Sala da Bluey"><img class="ku-cover-balloon" src="'+base+'balao-vermelho-v1.webp" alt=""><span class="cover-badge">🎈 NÃO DEIXE CAIR</span></div><div class="game-card-copy"><small>UMA BRINCADEIRA EM FAMÍLIA</small><h2>Manter no Alto <span>↗</span></h2><p>Corra com Bluey e Bingo para salvar os balões!</p></div></button>');app.querySelector('#ku-open').onclick=setup;}};
const oldCatalog=showCatalog;showCatalog=function(){stop();oldCatalog()};home();
})();
